const panel = document.getElementById('mima-author-root');
panel.innerHTML = '<h3>作者变量按钮</h3><p>按钮只更新本故事变量，不调用模型。</p><button id="score-add">三类变量各加一</button><pre id="score-view"></pre>';
const options = [{type:'chat'}, {type:'message', message_id:-1}, {type:'script'}];
for (const option of options) { const variables = getVariables(option); if (variables.score === undefined) replaceVariables({...variables, score:0}, option); }
function paint() { document.getElementById('score-view').textContent = JSON.stringify({chat:getVariables(options[0]), latestMessage:getVariables(options[1]), script:getVariables(options[2]), floor:getLastMessageId(), lastMessage:getChatMessages(-1)[0]?.message, host:MimaAuthor.getStatus()},null,2); }
document.getElementById('score-add').onclick = async () => {
  const button = document.getElementById('score-add'); button.disabled = true;
  try { for (const option of options) updateVariablesWith(variables => ({...variables, score:Number(variables.score || 0)+1}), option);
    document.getElementById('score-view').textContent = '待保存，正在等待提交回执';
    await MimaAuthor.whenCommitted(); paint();
  } catch (error) { document.getElementById('score-view').textContent = error.code + ': ' + error.message; }
  finally { button.disabled = false; }
};
MimaAuthor.whenCommitted().then(paint);
